import axios from "axios";
import { useloggedUserInfo } from "./stores/UserInfo";
// Our APIGATEWAY URL
const baseDomain = process.env.VUE_APP_API_URL;
const baseURL = `${baseDomain}`;
const baseCommonURL = process.env.VUE_APP_COMMON_API;
const baseURLCommon = `${baseCommonURL}`;
const baseDocStorage = process.env.VUE_APP_DOCSTORAGE_API;
const baseDocStorageUrl = `${baseDocStorage}`
const baseDomainTimer = process.env.VUE_APP_TIMER_API_URL;
const baseURLTimer = `${baseDomainTimer}`;
const baseDomainBilling =process.env.VUE_APP_BILLINGENGINE_URL;
const baseURLBilling =`${baseDomainBilling}`
const baseCompanyURL = process.env.VUE_APP_COMPANY_API_URL;
const baseURLCompany = `${baseCompanyURL}`;
const basedomainCrmCore=process.env.VUE_APP_CRM_CORE_URL;
const baseUrlCrmCore=`${basedomainCrmCore}`;
const baseTicketingUrl=process.env.VUE_APP_TICKETING_API_URL;
const baseUrlTicketing=`${baseTicketingUrl}`;
const instanceTimer = axios.create({
    baseURL: baseURLTimer,
});
const instance = axios.create({
    baseURL,
});
const instanceCommon = axios.create({
    baseURL: baseURLCommon,
});
const instancebaseDocStorage = axios.create({
    baseURL: baseDocStorageUrl
});
const instancebaseBilling = axios.create({
    baseURL: baseURLBilling
});
const instanceCompany = axios.create({
    baseURL: baseURLCompany,
})
const instanceCrmCore = axios.create({
    baseURL: baseUrlCrmCore,
})
const instanceTicketing = axios.create({
    baseURL: baseUrlTicketing,
})
instance.interceptors.request.use(
    (config) => {
        const token = useloggedUserInfo().GetUserInfo.Token;
        if (token) {
            config.headers["Authorization"] = `Bearer ${token}`;
            config.headers["content-type"] = config.url == '/ImportProjectPost' ? "multipart/form-data" : "application/json;charset=UTF-8";
            config.headers['Access-Control-Allow-Origin'] = '*';
        }
        return config;
    },
    (error) => {
        return Promise.reject(error);
    }
);
